// Morph helper for GNOME Shell 45+ (Wayland).
//
// Wayland gives ordinary apps no way to see other windows, float a small
// window over them, or read the clipboard while another app is in front.
// GNOME Shell can do all three, so this helper does them for Morph:
//
//  Front window
//    Get() -> base64(JSON {app, title, pill})
//    signal Changed(base64(JSON))            focus or the focused title changed
//  Clipboard
//    ReadClipboard() -> base64(JSON {mimetypes, text, html, secret})
//    ReadImage()     -> base64(JSON {path}) the copied image saved as a private temp file (only when asked: OCR)
//    WriteClipboard(mimetype, base64(data))  one format (fallback for the app)
//    signal ClipboardChanged("")             something new was copied
//  The pill (a slim black tab on the right edge, drawn by GNOME itself)
//    SetPill(base64(JSON spec))              the app says what to draw:
//      { visible, theme, size: 's'|'m'|'l', openNow, chips: 'chips'|'tiles', settled,
//        dot: 'none'|'has'|'ok',
//        handleColor, yFrac, side: 'l'|'r', monitor,
//        title, sub, subTone: ''|'ok'|'warn',
//        primary: {label, hint, action, color, busy, done} | null,
//        secondary: {label, action} | null,
//        section, options: [[{label, action, color, busy, done}]],
//        groups: [{title, rows: [[{label, action, color}]]}],
//        recentTitle, recent: [{label, hint, action, busy}],
//        links: [{label, action, color, hint}], collapseAfterMs }
//      Settings panes (v12+): pane.actions = [{icon, label, sub, action, confirm?: {title, body, ok}}] are
//      plain buttons; with confirm, GNOME's own dialog asks first.
//    signal Action("<verb>:<arg>")           what you clicked, or where you dragged
//                                            it: "moved:r0y420" (edge, monitor, y‰)
//    Paste(shift)                            press Ctrl V (Ctrl Shift V) in the
//                                            window in front, after a fix
//    SetShortcuts(base64(JSON [{id, accel}])) -> base64(JSON [ids GNOME refused])
//                                            pressing one emits Action("key:<id>")
import GLib from 'gi://GLib';
import Gio from 'gi://Gio';
import St from 'gi://St';
import Clutter from 'gi://Clutter';
import Meta from 'gi://Meta';
import Shell from 'gi://Shell';
import * as Main from 'resource:///org/gnome/shell/ui/main.js';
import { Slider } from 'resource:///org/gnome/shell/ui/slider.js';
import * as ModalDialog from 'resource:///org/gnome/shell/ui/modalDialog.js';
import { Extension } from 'resource:///org/gnome/shell/extensions/extension.js';

const PILL_VERSION = 23;
const IFACE = `
<node>
  <interface name="dev.morph.Focus">
    <method name="Get"><arg type="s" direction="out" name="info"/></method>
    <method name="SetPill"><arg type="s" direction="in" name="state"/></method>
    <method name="ReadClipboard"><arg type="s" direction="out" name="clip"/></method>
    <method name="ReadImage"><arg type="s" direction="out" name="image"/></method>
    <method name="Paste"><arg type="b" direction="in" name="shift"/></method>
    <method name="SetShortcuts"><arg type="s" direction="in" name="list"/><arg type="s" direction="out" name="failed"/></method>
    <method name="WriteClipboard"><arg type="s" direction="in" name="mimetype"/><arg type="s" direction="in" name="data"/></method>
    <signal name="Changed"><arg type="s" name="info"/></signal>
    <signal name="ClipboardChanged"><arg type="s" name="unused"/></signal>
    <signal name="Action"><arg type="s" name="action"/></signal>
  </interface>
</node>`;
