      const tile = new St.Bin({ style_class: small ? 'fb-sico' : 'fb-dico' + (brand ? '' : ' fb-dico-ui'), y_align: Clutter.ActorAlign.CENTER, x_align: Clutter.ActorAlign.CENTER });
      const ic = new St.Icon({ gicon: Gio.icon_new_for_string(this._iconFiles[key]), x_align: Clutter.ActorAlign.CENTER, y_align: Clutter.ActorAlign.CENTER });
      if (small) ic.set_style('icon-size: 14px;'); // pinned: never the 48px default
