    const label = new St.Label({ style_class: 'fb-btn-label', text: str(o.label, 40), x_expand: !!expand, y_align: Clutter.ActorAlign.CENTER });
    label.clutter_text.ellipsize = ELLIPSIZE_END;
    row.add_child(label);
    if (o.hint) row.add_child(new St.Label({ style_class: 'fb-btn-hint', text: str(o.hint, 24), y_align: Clutter.ActorAlign.CENTER }));
